def __repr__(self):
    return '<%s %r %r>' % (self.__class__.__name__, self.fixed,
        self.named)

def __contains__(self, item):
    '''Check if item is present as a key or value in the result.'''
    if item in self.named:
        return True
    if item in self.fixed:
        return True
    if item in self.named.values():
        return True
    return False
